<?php
namespace App\Models; use App\Core\Database;
final class Book{public function all():array{return Database::connection()->query('SELECT b.*,c.name category FROM books b LEFT JOIN categories c ON c.id=b.category_id ORDER BY b.title')->fetchAll();}public function categories():array{return Database::connection()->query('SELECT * FROM categories ORDER BY name')->fetchAll();}public function create(array $d):void{$q=Database::connection()->prepare('INSERT INTO books(isbn,title,author,category_id,quantity,available_quantity,classification,publisher,publication_year,acquired_at,condition_status,description) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$qty=max(1,(int)$d['quantity']);$q->execute([trim($d['isbn']),trim($d['title']),trim($d['author']),$d['category_id']?:null,$qty,$qty,$d['classification']??null,$d['publisher']??null,$d['publication_year']?:null,$d['acquired_at']?:null,$d['condition_status']??'good',$d['description']??null]);}}
